import { describe, expect, it, vi } from 'vitest'
import { ApiError, listIssues } from '../api'
import { jsonResponse, sampleApiIssues } from './fakeApi'

describe('listIssues', () => {
  it('asks GET /issues and returns the issues', async () => {
    const fetchMock = vi.fn(async (_url: string) => jsonResponse(sampleApiIssues))
    vi.stubGlobal('fetch', fetchMock)

    const result = await listIssues()

    expect(fetchMock).toHaveBeenCalledTimes(1)
    expect(fetchMock.mock.calls[0]?.[0]).toBe('/issues')
    expect(result).toHaveLength(4)
    expect(result[0]?._id).toBe('000000000000000000000001')
    expect(result[0]?.title).toBe('Login button does nothing')
  })

  it('throws an ApiError that carries the status and the server message when the answer is not ok', async () => {
    vi.stubGlobal('fetch', vi.fn(async () => jsonResponse({ error: 'Sign in required' }, 401)))

    const error = await listIssues().catch((e: unknown) => e)

    expect(error).toBeInstanceOf(ApiError)
    expect((error as ApiError).status).toBe(401)
    expect((error as ApiError).message).toBe('Sign in required')
  })

  it('still throws an ApiError when the server sends something that is not JSON', async () => {
    vi.stubGlobal('fetch', vi.fn(async () => new Response('<html>Bad gateway</html>', { status: 502 })))

    const error = await listIssues().catch((e: unknown) => e)

    expect(error).toBeInstanceOf(ApiError)
    expect((error as ApiError).status).toBe(502)
    expect((error as ApiError).message).toBe('Request failed (502)')
  })

  it('does not trust the network: an answer with the wrong shape is rejected', async () => {
    const broken = [{ _id: '1', priority: 'high' }] // no title, no status, nothing else
    vi.stubGlobal('fetch', vi.fn(async () => jsonResponse(broken)))

    await expect(listIssues()).rejects.toThrow()
  })

  it('lets a network failure through as a plain error', async () => {
    vi.stubGlobal('fetch', vi.fn(async () => { throw new TypeError('Failed to fetch') }))

    const error = await listIssues().catch((e: unknown) => e)

    expect(error).toBeInstanceOf(Error)
    expect(error).not.toBeInstanceOf(ApiError)
  })
})
